```python
import os
from openai import OpenAI

prompt = os.environ["PROMPT_TEXT"]
image_url = os.environ.get("IMAGE_URL")

content = [
    {
        "type": "text",
        "text": prompt,
    }
]

if image_url:
    content.append(
        {
            "type": "image_url",
            "image_url": {
                "url": image_url,
            },
        }
    )

client = OpenAI(
    api_key=os.environ["REQUESTY_API_KEY"],
    base_url="",
)

response = client.chat.completions.create(
    model="grok-4.3",
    reasoning_effort="high",
    messages=[
        {
            "role": "user",
            "content": content,
        }
    ],
    extra_body={
        "requesty": {
            "auto_cache": True,
        }
    },
)

print(response.choices[0].message.content)
```
